R"VICTUSMSL(#include <metal_stdlib>
#include <simd/simd.h>

using namespace metal;

struct Object
{
    float4x4 model;
    float4x4 normal_matrix;
};

struct Frame
{
    float4x4 view_proj;
    float4x4 light_view_proj;
};

struct main0_out
{
    float3 v_world_pos [[user(locn0)]];
    float3 v_normal [[user(locn1)]];
    float2 v_uv [[user(locn2)]];
    float4 v_tangent [[user(locn3)]];
    float4 v_shadow_pos [[user(locn4)]];
    float4 gl_Position [[position]];
};

struct main0_in
{
    float3 in_pos [[attribute(0)]];
    float3 in_normal [[attribute(1)]];
    float2 in_uv [[attribute(2)]];
    float4 in_tangent [[attribute(3)]];
};

vertex main0_out main0(main0_in in [[stage_in]], constant Frame& frame [[buffer(0)]], constant Object& object [[buffer(1)]])
{
    main0_out out = {};
    float4 world = object.model * float4(in.in_pos, 1.0);
    out.v_world_pos = world.xyz;
    out.v_normal = fast::normalize(float3x3(object.normal_matrix[0].xyz, object.normal_matrix[1].xyz, object.normal_matrix[2].xyz) * in.in_normal);
    out.v_tangent = float4(fast::normalize(float3x3(object.model[0].xyz, object.model[1].xyz, object.model[2].xyz) * in.in_tangent.xyz), in.in_tangent.w);
    out.v_uv = in.in_uv;
    out.v_shadow_pos = frame.light_view_proj * world;
    out.gl_Position = frame.view_proj * world;
    return out;
}

)VICTUSMSL";
